        T x=1237 y=214.3 w=200 h=53.4 text="{$row4_r1:%.1f}" size=34 font="Barlow SemiBold" f==if(eq($row4_st,2),#F2B233,if(eq($row4_st,3),#F7777A,#FFFFFF)) sh=[[0,2,2,0,#00000099]] align=right valign=middle fit=ellipsis
