        R x=1011.5 y=274.2 w=439 h=52.4 rx=5.5 f=@theme_row s=#5A5A69 sw=1
        T x=1025 y=273.7 w=202 h=53.4 text="Occupied for" size=28 font="Barlow SemiBold" f=#FFFFFF sh=[[0,2,2,0,#00000099]] valign=middle fit=ellipsis
