    }
    # widget alert al1 {"x":1011,"y":337.6,"w":440,"h":36.4,"row":false,"keys":{}}
    G id=al1 {
        R x=1011 y=337.6 w=440 h=36.4
        G v==gt($al1_st,0) {
            R x=1025 y=338.4 w=86 h=34.8 rx=4 f==if(eq($al1_st,1),#7FD970,if(eq($al1_st,2),#F2B233,if(eq($al1_st,3),#F7777A,#A6A6B4)))
